{"action": "write", "path": "semver.py", "content": """"Semantic version (SemVer 2.0.0) precedence sorting helper."""


def _is_numeric(identifier):
    return identifier.isdigit() and all(c in "0123456789" for c in identifier)


def _parse(version):
    """Split a version string into (major, minor, patch, prerelease)."""
    text = version.strip()

    # Build metadata is everything after the first '+' and is ignored.
    plus = text.find("+")
    if plus != -1:
        text = text[:plus]

    # Pre-release is everything after the first '-'.
    dash = text.find("-")
    if dash != -1:
        core = text[:dash]
        prerelease = text[dash + 1:]
    else:
        core = text
        prerelease = None

    major, minor, patch = core.split(".")
    return int(major), int(minor), int(patch), prerelease


def _prerelease_key(prerelease):
    """Return a comparable key for the pre-release portion.

    A version without a pre-release has higher precedence than the same
    version with one, so it maps to (1,) while pre-releases map to
    (0, identifiers).
    """
    if prerelease is None:
        return (1,)

    identifiers = []
    for ident in prerelease.split("."):
        if _is_numeric(ident):
            # Numeric identifiers sort as integers and below alphanumeric ones.
            identifiers.append((0, int(ident)))
        else:
            # Alphanumeric identifiers sort in ASCII order.
            identifiers.append((1, ident))
    # Tuple comparison: identifiers left to right, shorter list lower on ties.
    return (0, tuple(identifiers))


def _sort_key(version):
    major, minor, patch, prerelease = _parse(version)
    return (major, minor, patch, _prerelease_key(prerelease))


def sort_versions(vs):
    """Return the versions sorted by SemVer 2.0.0 precedence, lowest first.

    Ties preserve the original input order (stable sort).
    """
    return sorted(vs, key=_sort_key)
